import csv, re, json
from datetime import date
from collections import defaultdict

RUN_DATE = date(2026,6,30)
JUNE_START = date(2026,6,1)
JUNE_END = date(2026,6,30)

def money(s):
    s = s.strip().replace('$','').replace(',','')
    neg = False
    if s.startswith('-'):
        neg = True
        s = s[1:]
    val = float(s)
    return -val if neg else val

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

lines = read_csv('input/commission_lines.csv')
ledger = read_csv('input/netsuite_revenue_june.csv')
customers = {r['customer_id'].lower(): r for r in read_csv('input/customer_master.csv')}
exceptions = read_csv('input/commission_exceptions.csv')
co_sell = read_csv('input/co_sell_register.csv')

# ledger by deal
ledger_by_deal = defaultdict(list)
for r in ledger:
    deal = r['deal_ref'].lower()
    d = date.fromisoformat(r['posting_date'])
    amt = money(r['amount_usd'])
    ledger_by_deal[deal].append((d, r['customer_id'], amt, r))

def june_postings(deal):
    return [p for p in ledger_by_deal.get(deal.lower(), []) if JUNE_START <= p[0] <= JUNE_END]

def net_june(deal):
    return sum(amt for d,c,amt,r in june_postings(deal))

def customer_for_line(line):
    postings = june_postings(line['deal_id'])
    if postings:
        return postings[0][1]
    return line['customer_id']

def end_user_type(cust_id):
    cm = customers[cust_id.lower()]
    if cm['account_class'].lower() == 'house':
        return 'house'
    fid = date.fromisoformat(cm['first_invoice_date'])
    return 'new' if fid >= date(2025,7,1) else 'renewal'

def standard_rate(t):
    return {'new':8.0, 'renewal':4.0, 'house':0.0}[t]

def active_override(deal):
    for e in exceptions:
        if e['deal_id'].lower() == deal.lower():
            if e['status'].lower() == 'active':
                ef = date.fromisoformat(e['effective_from'])
                et = date.fromisoformat(e['effective_to'])
                if ef <= RUN_DATE <= et:
                    return e
    return None

def paid_rate(line):
    ov = active_override(line['deal_id'])
    if ov:
        return float(ov['approved_rate_pct'])
    return standard_rate(end_user_type(customer_for_line(line)))

# duplicate/co-sell
by_deal = defaultdict(list)
for l in lines:
    by_deal[l['deal_id'].lower()].append(l)

def co_sell_ok(deal):
    rows = [r for r in co_sell if r['deal_id'].lower() == deal.lower()]
    if not rows:
        return False
    if any(r['status'].lower() != 'active' for r in rows):
        return False
    reg_partners = sorted(r['partner'].lower() for r in rows)
    line_partners = sorted(l['source_report'].lower() for l in by_deal[deal])
    if reg_partners != line_partners or len(rows) != len(by_deal[deal]):
        return False
    if abs(sum(float(r['share_pct']) for r in rows) - 100.0) > 1e-9:
        return False
    return True

dup_deals = {deal for deal, ls in by_deal.items() if len(ls) > 1 and not co_sell_ok(deal)}

def share_for(deal, partner):
    for r in co_sell:
        if r['deal_id'].lower() == deal.lower() and r['partner'].lower() == partner.lower():
            return float(r['share_pct']) / 100.0
    return None

findings = []
rows = []
for l in lines:
    deal = l['deal_id'].lower()
    pr = paid_rate(l)
    rr = float(l['reported_rate_pct'])
    rev = float(l['revenue_usd'])
    commissionable = pr > 0
    dup = deal in dup_deals
    if commissionable:
        net = net_june(l['deal_id'])
        if co_sell_ok(deal):
            expected = net * share_for(deal, l['source_report'])
        else:
            expected = net
        matched = abs(expected - rev) <= 0.01 * rev
    else:
        matched = True
        expected = None
    if dup:
        code = 'DUPLICATE_LINE'
    elif commissionable and not matched:
        code = 'UNMATCHED_TO_LEDGER'
    elif abs(rr - pr) > 1e-9:
        code = 'RATE_MISMATCH'
    else:
        code = 'COMPLIANT'
    rows.append((l['line_id'], l['deal_id'], l['source_report'], l['customer_id'], customer_for_line(l), end_user_type(customer_for_line(l)), pr, rr, rev, net_june(l['deal_id']), expected, code))
    if code != 'COMPLIANT':
        findings.append((l['line_id'], l['deal_id'], l['source_report'], code))

for r in rows:
    print(r)
print('COUNTS', {c: sum(1 for r in rows if r[-1]==c) for c in ['DUPLICATE_LINE','UNMATCHED_TO_LEDGER','RATE_MISMATCH','COMPLIANT']}, 'total', len(rows))
print('FLAGGED', [(f[0], f[3]) for f in findings])
